// Object.is shallow compare — the exact gate React.memo applies.
function shallowEqual(a, b) {
  const ka = Object.keys(a), kb = Object.keys(b);
  if (ka.length !== kb.length) return false;
  for (const k of ka) { if (!Object.is(a[k], b[k])) return false; }
  return true;
}

// A stable callback reference (as if returned by useCallback with unchanged deps).
const stableOnClick = function () {};

// Case 1: parent re-renders; child gets the SAME stable reference back.
const case1 = {
  label: 'stable-ref',
  oldProps: { onClick: stableOnClick, count: 1 },
  newProps: { onClick: stableOnClick, count: 1 },
};

// Case 2: parent re-renders; child gets a FRESH inline object literal.
const case2 = {
  label: 'inline-object',
  oldProps: { style: { color: 'red' }, count: 1 },
  newProps: { style: { color: 'red' }, count: 1 }, // identical CONTENTS, new reference
};

